CREATE TRIGGER trg_points_on_submission_update AFTER UPDATE OF logged_views, submitted_at, challenge_id, creator_id, platform ON submissions FOR EACH ROW WHEN (old.logged_views IS DISTINCT FROM new.logged_views OR old.submitted_at IS DISTINCT FROM new.submitted_at OR old.challenge_id IS DISTINCT FROM new.challenge_id OR old.creator_id IS DISTINCT FROM new.creator_id OR old.platform IS DISTINCT FROM new.platform) EXECUTE FUNCTION trg_recalc_points();
CREATE TRIGGER trg_protect_logged_views BEFORE UPDATE ON submissions FOR EACH ROW EXECUTE FUNCTION protect_logged_views();
CREATE TRIGGER trg_results_follow_deleted_entry AFTER DELETE ON submissions FOR EACH ROW EXECUTE FUNCTION results_follow_deleted_entry();
CREATE TRIGGER trg_submission_collab_linked AFTER INSERT ON submissions FOR EACH ROW WHEN (new.collab_of IS NOT NULL) EXECUTE FUNCTION submission_collab_linked();
CREATE TRIGGER trg_submission_collab_unlinked AFTER DELETE ON submissions FOR EACH ROW WHEN (old.collab_of IS NOT NULL) EXECUTE FUNCTION submission_collab_unlinked();
CREATE TRIGGER trg_submission_posted_at BEFORE INSERT OR UPDATE OF platform_video_id, video_url, platform ON submissions FOR EACH ROW EXECUTE FUNCTION submission_posted_at_fill();
CREATE TRIGGER trg_submission_removed_seen BEFORE UPDATE OF views_sync_error, views_synced_at ON submissions FOR EACH ROW EXECUTE FUNCTION submission_removed_seen();
CREATE TRIGGER trg_submission_voucher_day AFTER INSERT OR UPDATE OF logged_views, posted_at ON submissions FOR EACH ROW EXECUTE FUNCTION trg_submission_voucher_day();
CREATE TRIGGER trg_submission_zz_disqualify_early AFTER UPDATE ON submissions FOR EACH ROW WHEN (new.posted_at IS NOT NULL AND old.posted_at IS DISTINCT FROM new.posted_at) EXECUTE FUNCTION submission_disqualify_early();
CREATE TRIGGER trg_submission_zz_refuse_early BEFORE INSERT ON submissions FOR EACH ROW EXECUTE FUNCTION submission_refuse_early();
CREATE TRIGGER trg_submission_zz_remove_when_gone AFTER UPDATE OF views_sync_error, views_synced_at ON submissions FOR EACH ROW WHEN (new.views_sync_error = 'removed'::text) EXECUTE FUNCTION submission_remove_when_gone();
CREATE TRIGGER trg_track_video_on_views_synced AFTER UPDATE OF logged_views ON submissions FOR EACH ROW WHEN (old.logged_views IS DISTINCT FROM new.logged_views) EXECUTE FUNCTION trg_track_video_on_views_synced();
CREATE TRIGGER survey_sample_guard BEFORE INSERT OR UPDATE ON survey_responses FOR EACH ROW EXECUTE FUNCTION survey_sample_guard();
CREATE TRIGGER surveys_touch BEFORE UPDATE ON surveys FOR EACH ROW EXECUTE FUNCTION surveys_touch();
CREATE TRIGGER trg_tracked_videos_touch BEFORE UPDATE ON tracked_videos FOR EACH ROW EXECUTE FUNCTION tracked_videos_touch();
CREATE TRIGGER trg_vip_notify_bonus AFTER INSERT ON vip_bonus_awards FOR EACH ROW EXECUTE FUNCTION vip_notify_bonus();
CREATE TRIGGER trg_audit_vip_bonus_rules AFTER INSERT OR DELETE ON vip_bonus_rules FOR EACH ROW EXECUTE FUNCTION audit_change('money', 'VIP bonus rule', 'label');
CREATE TRIGGER trg_audit_vip_bonus_rules_upd AFTER UPDATE ON vip_bonus_rules FOR EACH ROW EXECUTE FUNCTION audit_change('money', 'VIP bonus rule', 'label', 'amount', 'places', 'conditions', 'active', 'reward', 'multiplier');
CREATE TRIGGER trg_audit_vip_members AFTER INSERT OR DELETE ON vip_members FOR EACH ROW EXECUTE FUNCTION audit_change('money', 'VIP member', '');
CREATE TRIGGER trg_audit_vip_members_upd AFTER UPDATE ON vip_members FOR EACH ROW EXECUTE FUNCTION audit_change('money', 'VIP member', '', 'status', 'cpm', 'monthly_cap', 'target_videos', 'target_views');
CREATE TRIGGER trg_vip_leaves_challenge_boards AFTER INSERT OR UPDATE OF status ON vip_members FOR EACH ROW EXECUTE FUNCTION vip_leaves_challenge_boards();
CREATE TRIGGER trg_vip_log_member AFTER INSERT OR UPDATE ON vip_members FOR EACH ROW EXECUTE FUNCTION vip_log_member();
CREATE TRIGGER trg_vip_member_flag AFTER INSERT OR DELETE OR UPDATE ON vip_members FOR EACH ROW EXECUTE FUNCTION vip_member_flag();
CREATE TRIGGER trg_vip_notify_joined AFTER INSERT OR UPDATE OF status, programme_id ON vip_members FOR EACH ROW EXECUTE FUNCTION vip_notify_joined();
CREATE TRIGGER trg_audit_vip_programmes AFTER INSERT OR DELETE ON vip_programmes FOR EACH ROW EXECUTE FUNCTION audit_change('money', 'VIP programme', 'name');
CREATE TRIGGER trg_audit_vip_programmes_upd AFTER UPDATE ON vip_programmes FOR EACH ROW EXECUTE FUNCTION audit_change('money', 'VIP programme', 'name', 'cpm', 'tiers', 'min_payout', 'monthly_cap', 'budget_monthly', 'window_days', 'active');
CREATE TRIGGER award_vip_podium_certificates AFTER UPDATE OF status ON vip_statements FOR EACH ROW EXECUTE FUNCTION on_vip_statement_certificates();
CREATE TRIGGER trg_audit_vip_statements_upd AFTER UPDATE ON vip_statements FOR EACH ROW EXECUTE FUNCTION audit_change('money', 'VIP statement', '', 'status', 'total', 'adjustments');
CREATE TRIGGER award_entry_certificate AFTER INSERT ON vip_videos FOR EACH ROW EXECUTE FUNCTION on_entry_certificate();
CREATE TRIGGER trg_aa_refuse_photo_post BEFORE INSERT ON vip_videos FOR EACH ROW EXECUTE FUNCTION refuse_photo_post();
CREATE TRIGGER trg_limit_vip_videos BEFORE INSERT ON vip_videos FOR EACH ROW EXECUTE FUNCTION enforce_write_limit('profile_id', 'submitted_at', '30', '600');
CREATE TRIGGER trg_vip_read_new_video AFTER INSERT ON vip_videos FOR EACH ROW EXECUTE FUNCTION vip_read_new_video();
CREATE TRIGGER trg_vip_video_fill BEFORE INSERT OR UPDATE OF platform_video_id, video_url, platform ON vip_videos FOR EACH ROW EXECUTE FUNCTION vip_video_fill();
CREATE TRIGGER enforce_bucket_name_length_trigger BEFORE INSERT OR UPDATE OF name ON storage.buckets FOR EACH ROW EXECUTE FUNCTION storage.enforce_bucket_name_length();
CREATE TRIGGER protect_bucket_control_insert BEFORE INSERT ON storage.buckets FOR EACH ROW EXECUTE FUNCTION storage.protect_bucket_control_columns('service_role');
CREATE TRIGGER protect_bucket_control_update BEFORE UPDATE OF lifecycle_configuration, lifecycle_configuration_generation ON storage.buckets FOR EACH ROW EXECUTE FUNCTION storage.protect_bucket_control_columns();
CREATE TRIGGER protect_bucket_control_update_role AFTER UPDATE OF lifecycle_configuration, lifecycle_configuration_generation ON storage.buckets FOR EACH ROW EXECUTE FUNCTION storage.enforce_bucket_lifecycle_service_role('service_role');
CREATE TRIGGER protect_buckets_delete BEFORE DELETE ON storage.buckets FOR EACH STATEMENT EXECUTE FUNCTION storage.protect_delete();
CREATE TRIGGER protect_objects_delete BEFORE DELETE ON storage.objects FOR EACH STATEMENT EXECUTE FUNCTION storage.protect_delete();
CREATE TRIGGER update_objects_updated_at BEFORE UPDATE ON storage.objects FOR EACH ROW EXECUTE FUNCTION storage.update_updated_at_column();

-- Event triggers (fire on DDL, not on rows)
-- issue_graphql_placeholder: on sql_drop {"DROP EXTENSION"} -> set_graphql_placeholder
-- issue_pg_cron_access: on ddl_command_end {"CREATE EXTENSION"} -> grant_pg_cron_access
-- issue_pg_graphql_access: on ddl_command_end {"CREATE EXTENSION"} -> grant_pg_graphql_access
-- issue_pg_net_access: on ddl_command_end {"CREATE EXTENSION"} -> grant_pg_net_access
-- no_new_function_is_public: on ddl_command_end {"CREATE FUNCTION","ALTER FUNCTION"} -> no_new_function_is_public
-- pgrst_ddl_watch: on ddl_command_end -> pgrst_ddl_watch
-- pgrst_drop_watch: on sql_drop -> pgrst_drop_watch
